func TestEnumLanguage(t *testing.T) {
	t.Run("NewFromString_JAVA", func(t *testing.T) {
		t.Parallel()
		val, err := NewLanguageFromString("JAVA")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, Language("JAVA"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_JAVASCRIPT", func(t *testing.T) {
		t.Parallel()
		val, err := NewLanguageFromString("JAVASCRIPT")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, Language("JAVASCRIPT"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_PYTHON", func(t *testing.T) {
		t.Parallel()
		val, err := NewLanguageFromString("PYTHON")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, Language("PYTHON"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewLanguageFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewLanguageFromString("JAVA")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesBinaryTreeNodeValue(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &BinaryTreeNodeValue{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *BinaryTreeNodeValue
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}

